package state

import (
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"testing"

	"devshard/signing"
	"github.com/stretchr/testify/require"
)

func compatibilityFixture(t *testing.T) journalFixture {
	t.Helper()
	keys := make([]*signing.Secp256k1Signer, 6)
	for i := range keys {
		var err error
		keys[i], err = signing.SignerFromHex(fmt.Sprintf("%064x", i+1))
		require.NoError(t, err)
	}
	return journalFixture{hosts: keys[:5], user: keys[5]}
}

// Roots were generated by release/devshard/v4.1.0 (701fab877).
func TestV41ReleaseStateRoots(t *testing.T) {
	data, err := os.ReadFile("testdata/v41-state-roots.json")
	require.NoError(t, err)
	var roots []string
	require.NoError(t, json.Unmarshal(data, &roots))
	f := compatibilityFixture(t)
	sm := f.machine(t)
	st := sm.SnapshotState()
	st.StateRootAndProtocolVersion = "v4.1"
	sm.RestoreState(&st)
	root, err := sm.ComputeStateRoot()
	require.NoError(t, err)
	require.Equal(t, roots[0], hex.EncodeToString(root))
	steps := f.script(t)
	require.Len(t, roots, len(steps)+1)
	for i, txs := range steps {
		root, err = sm.ApplyLocal(uint64(i+1), txs)
		require.NoError(t, err)
		require.Equal(t, roots[i+1], hex.EncodeToString(root), "nonce %d", i+1)
	}
}
